#!/usr/bin/env python3
"""Build Session Helper - Reads HEARTBEAT.md, picks one task, logs session."""

from pathlib import Path
from datetime import datetime
import sys

HEARTBEAT_FILE = Path("HEARTBEAT.md")
NOTES_FILE = Path("project_notes.txt")
SESSION_LOG_FILE = Path("session_log.md")


def read_heartbeat():
    """Read HEARTBEAT.md and extract task ideas."""
    if not HEARTBEAT_FILE.exists():
        return None, []

    content = HEARTBEAT_FILE.read_text(encoding="utf-8")
    tasks = []

    for line in content.splitlines():
        stripped = line.strip()
        if stripped.startswith("- "):
            tasks.append(stripped[2:])

    return content, tasks


def pick_task(tasks):
    """Deterministically pick the first available task."""
    if not tasks:
        return "Review and organize pending items"
    return tasks[0]


def get_existing_notes():
    """Read existing project notes if they exist."""
    if NOTES_FILE.exists():
        return NOTES_FILE.read_text(encoding="utf-8")
    return ""


def format_session_log(task, timestamp):
    """Format a session log entry according to the Build Session Framework."""
    return f"""## Build Session: {timestamp} — {task}

### What I Built
Started work on: {task}

### Key Insights
- Task selected deterministically from HEARTBEAT.md
- Session logged for tracking progress

### Git
Pending commit
"""


def main():
    """Main entry point."""
    timestamp = datetime.now().strftime("%H:%M")

    # Read heartbeat file
    heartbeat_content, tasks = read_heartbeat()

    if heartbeat_content is None:
        print("Warning: HEARTBEAT.md not found. Creating default session.")
        task = "Initialize project structure"
    else:
        task = pick_task(tasks)

    # Get existing notes
    existing_notes = get_existing_notes()

    # Format new session entry
    session_entry = format_session_log(task, timestamp)

    # Append to session log
    if SESSION_LOG_FILE.exists():
        session_log = SESSION_LOG_FILE.read_text(encoding="utf-8")
        # Add separator if needed
        if session_log and not session_log.endswith("\n\n"):
            session_log += "\n\n"
    else:
        session_log = "# Session Log\n\n"

    session_log += session_entry
    SESSION_LOG_FILE.write_text(session_log, encoding="utf-8")

    # Also append to project notes
    if existing_notes and not existing_notes.endswith("\n\n"):
        existing_notes += "\n\n"
    existing_notes += session_entry
    NOTES_FILE.write_text(existing_notes, encoding="utf-8")

    print(f"Session started: {task}")
    print(f"Logged to: {SESSION_LOG_FILE}, {NOTES_FILE}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
